import argparse
import json
import re
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("payload")
args = json.loads(parser.parse_args().payload)
text = Path(args["path"]).read_text(encoding="utf-8").lower().replace("’", "'")

patterns = {
    "refund": [r"\brefund(?:ed|ing)?\b", r"\bmoney\s+back\b", r"\breimburse(?:ment|d)?\b"],
    "exchange": [r"\bexchange(?:d|ing)?\b", r"\breplace(?:ment|d)?\b", r"\bswap(?:ped|ping)?\b", r"\bdifferent\s+(?:size|colou?r)\b"],
    "cancellation": [r"\bcancel(?:lation|l?ed|l?ing)?\b", r"\bcall\s+off\b", r"\bterminate\b", r"\bstop\s+(?:my\s+)?(?:order|subscription)\b"],
}

scores = {label: 0 for label in patterns}
latest = {label: -1 for label in patterns}
negation = re.compile(r"(?:\bdo\s+not|\bdon't|\bnot|\bnever|\bno)\b(?:\W+\w+){0,3}\W*$")
intent_cue = re.compile(r"\b(?:want|need|please|request|prefer|would\s+like)\b")

for label, label_patterns in patterns.items():
    for pattern in label_patterns:
        for match in re.finditer(pattern, text):
            before = text[max(0, match.start() - 45):match.start()]
            after = text[match.end():match.end() + 20]
            if negation.search(before):
                scores[label] -= 4
            else:
                scores[label] += 2
                if intent_cue.search(before[-30:] + " " + after):
                    scores[label] += 2
                latest[label] = max(latest[label], match.start())

best_score = max(scores.values())
candidates = [label for label, score in scores.items() if score == best_score]
result = max(candidates, key=lambda label: (latest[label], {"refund": 2, "exchange": 1, "cancellation": 0}[label]))
print(result, end="")
